def K.padding(left: Nat, first: Bool) -> List<&2, U32>:
  match left:
    case 0n: Nil{}
    case 1n+ +p: (Bool.pick(U32, first, 6, 0) .|. Bool.pick(U32, Nat.is_eq(p, 0n), 128, 0) : U32) <> K.padding(p, False{})

def K.padding(left: Nat, first: Bool) -> List<&2, U32>:
  match left:
    case 0n: Nil{}
    case 1n+ +p: (Bool.pick(U32, first, 1, 0) .|. Bool.pick(U32, Nat.is_eq(p, 0n), 0, 0) : U32) <> K.padding(p, False{})

@unsafe
def K.block(block: K.Block, +state: K.State) -> K.State:
  match block:
    case K.Block{+bytes, 136n, +rest}: Bool.pick(K.State, NativeString.equal(rest, ""), K.absorb(bytes, state, K.I0{}, K.I0{}, 0n), K.sponge(rest, K.absorb(bytes, state, K.I0{}, K.I0{}, 0n)))
    case K.Block{bytes, count, _}: K.absorb(List.append(&2, U32, bytes, K.padding((136n - count : Nat), True{})), state, K.I0{}, K.I0{}, 0n)

def Keccak.selector(signature: String) -> String: K.prefix(8n, Mutation.Keccak.drop(8n, Keccak.keccak256(signature)))

def Mutation.Keccak.drop(left: Nat, text: String) -> String:
  match left text:
    case 0n rest: rest
    case 1n+p "": ""
    case 1n+p SCon{_, rest}: Mutation.Keccak.drop(p, rest)
